// Authorises the request and turns it into one n8n API call.
// Fail-closed: a missing, short or placeholder gatewayToken rejects every request,
// and only the actions listed in ACTIONS can reach the n8n API.
const MIN_TOKEN_LENGTH = 32; // `openssl rand -hex 32` gives 64 characters
const PLACEHOLDER = /^\s*(change[\s_-]?me|replace[\s_-]?me|your[\s_-])/i;
const MAX_PAGE_SIZE = 250; // n8n API cap
const MAX_CURSOR_LENGTH = 4096;
const ID = /^[A-Za-z0-9_-]{1,64}$/; // workflow and execution IDs; no dots or slashes, so no path tricks
const EXECUTION_STATUSES = ['canceled', 'error', 'running', 'success', 'waiting'];

const cfg = $json;
const headers = cfg.headers || {};
const body = cfg.body && typeof cfg.body === 'object' ? cfg.body : {};

const reply = (status, error, message) =>
  [{ json: { action_type: 'error', success: false, status, error, message } }];

const usable = (value) => typeof value === 'string' && value.trim() !== '' && !PLACEHOLDER.test(value);

// Compares every character of the longer string, so the time taken does not reveal
// how much of a guessed token was right.
function sameSecret(a, b) {
  let diff = a.length ^ b.length;
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
}

// 1. Gateway configuration and the caller's token, before anything else.
const expected = cfg.gatewayToken;
if (!usable(expected) || expected.trim().length < MIN_TOKEN_LENGTH) {
  return reply(503, 'Gateway not configured',
    'Set a unique gatewayToken (at least ' + MIN_TOKEN_LENGTH + ' characters) in the ⚙️ Config node.');
}
const presented = headers['x-api-key'];
if (typeof presented !== 'string' || !sameSecret(presented, expected.trim())) {
  return reply(401, 'Unauthorized', 'Invalid or missing X-API-Key header');
}

// 2. Request shape.
const action = typeof body.action === 'string' ? body.action.trim() : '';
const params = body.params === undefined ? {} : body.params;
if (!params || typeof params !== 'object' || Array.isArray(params)) {
  return reply(400, 'Bad request', '"params" must be a JSON object');
}

class BadParam extends Error {}
const id = (name) => {
  const v = params[name];
  const s = typeof v === 'number' && Number.isInteger(v) ? String(v) : v;
  if (typeof s !== 'string' || !ID.test(s)) throw new BadParam('"' + name + '" must be a valid ID');
  return encodeURIComponent(s);
};
const optional = (name, read) => (params[name] === undefined || params[name] === null ? undefined : read(name));
const limit = () => {
  const v = params.limit;
  if (!Number.isInteger(v) || v < 1 || v > MAX_PAGE_SIZE) throw new BadParam('"limit" must be 1–' + MAX_PAGE_SIZE);
  return v;
};
const cursor = () => {
  const v = params.cursor;
  if (typeof v !== 'string' || v.length > MAX_CURSOR_LENGTH) throw new BadParam('"cursor" must be a string');
  return v;
};
const status = () => {
  if (!EXECUTION_STATUSES.includes(params.status)) {
    throw new BadParam('"status" must be one of: ' + EXECUTION_STATUSES.join(', '));
  }
  return params.status;
};

// 3. The allowlist: exactly what the Orqflow apps use. Each entry names the params it
// accepts and builds a request on the fixed API base; anything else is refused.
const ACTIONS = {
  list_endpoints: { category: 'meta', params: [] },
  get_system_info: { category: 'meta', params: [] },
  list_workflows: {
    category: 'workflows', params: ['limit', 'cursor'],
    request: () => ({ method: 'GET', path: '/workflows',
      qs: { limit: optional('limit', limit) ?? 100, cursor: optional('cursor', cursor) } }),
  },
  get_workflow: {
    category: 'workflows', params: ['workflowId'],
    request: () => ({ method: 'GET', path: '/workflows/' + id('workflowId') }),
  },
  activate_workflow: {
    category: 'workflows', params: ['workflowId'],
    request: () => ({ method: 'POST', path: '/workflows/' + id('workflowId') + '/activate' }),
  },
  deactivate_workflow: {
    category: 'workflows', params: ['workflowId'],
    request: () => ({ method: 'POST', path: '/workflows/' + id('workflowId') + '/deactivate' }),
  },
  list_executions: {
    category: 'executions', params: ['limit', 'cursor', 'workflowId', 'status'],
    request: () => ({ method: 'GET', path: '/executions',
      qs: { limit: optional('limit', limit) ?? 20, cursor: optional('cursor', cursor),
        workflowId: optional('workflowId', id), status: optional('status', status) } }),
  },
  get_execution: {
    category: 'executions', params: ['executionId'],
    request: () => ({ method: 'GET', path: '/executions/' + id('executionId') }),
  },
  stop_execution: {
    category: 'executions', params: ['executionId'],
    request: () => ({ method: 'POST', path: '/executions/' + id('executionId') + '/stop' }),
  },
};

if (!Object.prototype.hasOwnProperty.call(ACTIONS, action)) {
  return reply(400, 'Unknown action', 'Action "' + action.slice(0, 64) + '" is not supported. Call list_endpoints for the available actions.');
}
const def = ACTIONS[action];
const extra = Object.keys(params).filter((k) => !def.params.includes(k));
if (extra.length) return reply(400, 'Bad request', 'Unsupported parameter(s) for ' + action + ': ' + extra.join(', ').slice(0, 200));

if (action === 'list_endpoints') {
  const categories = {};
  for (const [name, a] of Object.entries(ACTIONS)) (categories[a.category] ||= []).push(name);
  const endpoints = Object.keys(ACTIONS);
  return [{ json: { action_type: 'success', success: true, action, data: { total: endpoints.length, endpoints, categories } } }];
}
if (action === 'get_system_info') {
  return [{ json: { action_type: 'success', success: true, action, data: {
    api_version: 'v1', environment: $execution.mode, workflow_id: $workflow.id, workflow_name: $workflow.name,
    timestamp: new Date().toISOString() } } }];
}

// 4. Server side of the call: the n8n API key and address the gateway itself is configured with.
if (!usable(cfg.n8nApiKey)) {
  return reply(503, 'Gateway not configured', 'Set n8nApiKey in the ⚙️ Config node.');
}
// The Code node sandbox has no URL class; scheme, host and an optional path, nothing else.
const instanceUrl = typeof cfg.instanceUrl === 'string' ? cfg.instanceUrl.trim().replace(/\/+$/, '') : '';
if (!/^https?:\/\/[A-Za-z0-9.-]+(:\d{1,5})?(\/[A-Za-z0-9._~-]+)*$/.test(instanceUrl)) {
  return reply(503, 'Gateway not configured', 'Set instanceUrl in the ⚙️ Config node to an http(s) address of n8n.');
}

let req;
try {
  req = def.request();
} catch (e) {
  if (e instanceof BadParam) return reply(400, 'Bad request', e.message);
  throw e;
}
const qs = Object.fromEntries(Object.entries(req.qs || {}).filter(([, v]) => v !== undefined));
return [{ json: { action_type: 'api_call', action, method: req.method,
  url: instanceUrl + '/api/v1' + req.path, qsData: qs } }];

const res = $input.first().json;
const req = $('Map Action').first().json;
const selfId = $workflow.id;

// The request node continues on failure: no status code means n8n was not reached
// (wrong instanceUrl, DNS, TLS, timeout). The cause stays in this execution, not in the reply.
if (res.statusCode === undefined) {
  return [{ json: { success: false, action: req.action, httpStatus: 502,
    message: 'The gateway could not reach the n8n API. Check instanceUrl in the ⚙️ Config node.' } }];
}

// fullResponse: { statusCode, body, headers }. neverError keeps 4xx/5xx on this path,
// so the status code is the only reliable error signal.
const status = Number(res.statusCode);
const body = res.body;

if (status >= 400) {
  // n8n answers a bad API key with a bare "unauthorized", which in the app reads
  // like a wrong gateway token. Say which key is at fault; 403 is a missing API key scope.
  const msg = status === 401
    ? 'The n8n API key in the ⚙️ Config node is invalid or expired (n8n API returned 401).'
    : status === 403
      ? 'The n8n API key in the ⚙️ Config node lacks the scope for "' + req.action + '" (n8n API returned 403).'
      : (body && typeof body === 'object' && (body.message || body.error))
        || (typeof body === 'string' && body)
        || ('n8n API returned HTTP ' + status);
  return [{ json: { success: false, action: req.action, httpStatus: status, message: msg } }];
}

// List responses: { data: [...], nextCursor } -> { items, total, nextCursor }.
// The gateway hides itself: it is plumbing, and its own in-flight execution
// would otherwise always show up as "running".
let data = body;
if (body && Array.isArray(body.data)) {
  let items = body.data;
  if (req.action === 'list_workflows') items = items.filter(w => w.id !== selfId);
  if (req.action === 'list_executions') items = items.filter(e => e.workflowId !== selfId);
  data = { items, total: items.length, nextCursor: body.nextCursor || null };
}

return [{ json: { success: true, action: req.action, data } }];

// Runs after the app already got its answer. Every gateway request is saved as
// an execution of this workflow; left alone they crowd the head of n8n's history
// that the app pages through. Prune them in batches once enough piled up.
// Failed runs are kept for diagnosis. Disabling execution saving instead is not
// an option: on n8n 2.x it leaves every request stuck as "running".
const THRESHOLD = 50;
const res = $input.first().json;
const runs = (res.statusCode < 400 && res.body && Array.isArray(res.body.data)) ? res.body.data : [];
if (runs.length <= THRESHOLD) return [];
const current = String($execution.id);
return runs
  .filter(r => String(r.id) !== current)
  .map(r => ({ json: { id: r.id } }));
